def rearange_string(s):
  count_dict = {}
  for char in s:
    if char in count_dict:
      count_dict[char] += 1
    else:
      count_dict[char] = 1

  odd_count = 0
  for value in count_dict.values():
    if value % 2 != 0:
      odd_count += 1

  if odd_count > 1:
    return ""

  sorted_chars = sorted(count_dict.keys(), key=lambda x: count_dict[x])
  result = ""
  even_index = 0
  odd_index = 1

  while even_index < len(sorted_chars) or odd_index < len(sorted_chars):
    if even_index < len(sorted_chars):
      result += sorted_chars[even_index]
      even_index += 2
    if odd_index < len(sorted_chars):
      result += sorted_chars[odd_index]
      odd_index += 2

  return result

